#pragma once
namespace spark {
inline constexpr auto assistant_page=R"HTML(<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SPARK Assistant</title>
<style>body{margin:0;background:#101820;color:#e5edf3;font:16px system-ui}main{max-width:900px;margin:auto;padding:24px}a{color:#78dfcc}header,nav,.actions{display:flex;gap:12px;align-items:center;flex-wrap:wrap}header{justify-content:space-between}button,textarea{font:inherit;border-radius:8px;padding:12px}button{background:#78dfcc;color:#101820;border:0;cursor:pointer}button:disabled{opacity:.5;cursor:default}textarea{box-sizing:border-box;width:100%;background:#101820;color:#fff;border:1px solid #67818e;resize:vertical;min-height:110px}article,form{background:#1a2935;border:1px solid #334957;border-radius:12px;padding:20px;margin:18px 0}article.user{margin-left:8%;background:#203c46}article p,pre{white-space:pre-wrap;overflow-wrap:anywhere}pre{max-height:400px;overflow:auto;font-size:13px}summary{cursor:pointer;color:#78dfcc}label{display:block;margin-bottom:10px}.muted{color:#b0c3cf;font-size:14px}.actions{margin-top:14px}#status{min-height:24px}form{position:sticky;bottom:8px}button.secondary{background:#d3e0e6}h1{margin-bottom:6px}</style></head><body>
<main><nav><a href="/">← Dashboard</a><a href="/api/docs">API documentation</a></nav><header><div><h1>SPARK Assistant</h1><p class="muted">Ask about your projects, files, calendar and timers.</p></div><button id="new" class="secondary" disabled>New conversation</button></header>
<p id="status" role="status" aria-live="polite">Connecting…</p><div id="messages" role="log" aria-label="Conversation" aria-live="polite"></div>
<form id="form"><label for="query">Your message</label><textarea id="query" required placeholder="Search the SPARK project files for notification" disabled></textarea><div class="actions"><button id="send" disabled>Send</button><button type="button" id="retry" hidden>Recover last request</button><span class="muted">Enter to send · Shift+Enter for a new line</span></div><p class="muted">Follow-ups stay in this conversation. New conversation clears this page’s view; server history is retained. Replies may take up to two minutes.</p></form></main>
<script src="/auth/client.js"></script><script>
(()=>{'use strict';
const $=id=>document.getElementById(id);let conversation=null,confirmation=null,pending=null,busy=false,ready=false,target=null;
function controls(){for(const el of document.querySelectorAll('button'))el.disabled=busy||!ready;const unresolved=!!pending;$('send').disabled=busy||!ready||unresolved;$('new').disabled=busy||!ready||unresolved;$('query').disabled=busy||!ready||unresolved;$('retry').hidden=!unresolved;for(const el of document.querySelectorAll('[data-action]'))el.disabled=busy||!ready||unresolved||el.dataset.stale==='true';}
function status(text){$('status').textContent=text;}
function card(label,text){const el=document.createElement('article'),heading=document.createElement('strong'),body=document.createElement('p');heading.textContent=label;body.textContent=text;el.append(heading,body);$('messages').append(el);return el;}
function id(){const bytes=new Uint8Array(16);crypto.getRandomValues(bytes);return 'web-'+Array.from(bytes,b=>b.toString(16).padStart(2,'0')).join('');}
async function api(path,body){const opts=body===undefined?{cache:'no-store'}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)};const r=await fetch(path,opts);let data;try{data=await r.json();}catch(e){throw Error('Could not read the server response. Recover the last request before sending another.');}if(!r.ok&&!data.status){const e=Error(data.error||'Request failed');e.http=r.status;throw e;}return data;}
function stale(){for(const el of document.querySelectorAll('[data-confirm]')){el.dataset.stale='true';el.disabled=true;}}
function render(el,data){el.replaceChildren();const heading=document.createElement('strong'),body=document.createElement('p');heading.textContent='Assistant · '+(data.status||'result').replaceAll('_',' ');body.textContent=data.message||(data.status==='undone'?'Action undone.':'Result received.');el.append(heading,body);if(data.error){const error=document.createElement('p');error.textContent='Error: '+data.error;el.append(error);}const details=document.createElement('details'),summary=document.createElement('summary'),pre=document.createElement('pre');summary.textContent='Response details';pre.textContent=JSON.stringify(data,null,2);details.append(summary,pre);el.append(details);
 const actions=document.createElement('div');actions.className='actions';el.append(actions);
 function button(label,path,isConfirmation){const b=document.createElement('button');b.type='button';b.textContent=label;b.dataset.action='true';if(isConfirmation)b.dataset.confirm='true';b.onclick=async()=>{if(busy||pending)return;busy=true;controls();status('Working…');try{const result=await api(path,{});if(isConfirmation){stale();confirmation=null;}render(el,result);status(result.error?'The action was not completed.':'Ready.');}catch(e){status(e.message+' You can retry this same button safely.');}finally{busy=false;controls();}};actions.append(b);}
 if(data.status==='needs_confirmation'&&data.confirmation_id){confirmation=data.confirmation_id;const expiry=document.createElement('p');expiry.textContent='Confirm by '+new Date(data.confirmation_expires_at).toLocaleString();el.append(expiry);button('Confirm','/assistant/confirmations/'+encodeURIComponent(data.confirmation_id)+'/confirm',true);button('Cancel','/assistant/confirmations/'+encodeURIComponent(data.confirmation_id)+'/cancel',true);}
 if(data.file_search&&data.file_search.next_page_from){const b=document.createElement('button');b.type='button';b.textContent='Explore next files';b.dataset.action='true';b.dataset.page='true';b.onclick=()=>{if(busy||pending)return;for(const old of document.querySelectorAll('[data-page]'))old.dataset.stale='true';pending={request_id:id(),text:'Next page',file_page_from:data.file_search.next_page_from};card('You','Explore next files');target=card('Assistant','Reading the next page…');submit();};actions.append(b);}
 if(data.undo_available&&(data.action_id||data.id))button('Undo','/assistant/actions/'+encodeURIComponent(data.action_id||data.id)+'/undo',false);
 controls();el.scrollIntoView({block:'nearest'});
}
async function submit(){if(busy||!pending)return;busy=true;controls();status('SPARK is processing your request…');try{const result=await api('/assistant/requests',pending);if(result.conversation_id)conversation=result.conversation_id;stale();confirmation=null;render(target,result);if(result.status==='processing'){status('Outcome is not yet confirmed. Recover this request before sending another.');}else{pending=null;status(result.error?'Request finished with an error. You can send a new message.':'Ready.');}}catch(e){status(e.message);if(e.http&&e.http<500){pending=null;}}finally{busy=false;controls();if(!pending)$('query').focus();}}
$('form').onsubmit=e=>{e.preventDefault();if(busy||pending||!ready)return;const text=$('query').value.trim();if(!text)return;if(new TextEncoder().encode(text).length>8192){status('Keep your message below 8192 UTF-8 bytes.');return;}pending={request_id:id(),text};if(conversation)pending.conversation_id=conversation;const decision=text.toLowerCase().replace(/[.!?,]/g,'').trim();if(confirmation&&['yes','yes please','confirm','confirm it','go ahead','do it','no','no thanks','cancel','cancel it'].includes(decision))pending.confirmation_id=confirmation;const user=card('You',text);user.classList.add('user');target=card('Assistant','Working…');$('query').value='';submit();};
$('query').onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();$('form').requestSubmit();}};
$('retry').onclick=()=>submit();$('new').onclick=()=>{if(busy||pending)return;conversation=null;confirmation=null;$('messages').replaceChildren();status('New conversation.');$('query').focus();};
api('/assistant/setup').then(s=>{ready=s.enabled;status(ready?'Ready.':'The assistant is not configured on this instance.');controls();}).catch(e=>{status(e.message);controls();});
})();
</script></body></html>)HTML";
}
